// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8;

import { Ownable2Step } from "@openzeppelin/contracts/access/Ownable2Step.sol";
import "./StablePool.sol";

contract StableFactory is Ownable2Step {

    address[] public allPools;
    mapping (uint => address) internal poolMap;

    event PoolCreated(address poolAddr, address[] tokens);

    constructor() {}

    function allPoolsLength() external view returns (uint) {
        return allPools.length;
    }

    function createPool(
        address[] memory _tokens,
        string memory _name,
        string memory _symbol
    ) external onlyOwner returns (address poolAddr) {
        StablePool pool = new StablePool(_tokens, _name, _symbol);
        poolAddr = address(pool);

        uint key;
        for (uint i = 0; i < _tokens.length; i++) {
            key += uint(uint160(_tokens[i]));
        }
        require(poolMap[key] == address(0), "StableFactory::createPool: Pool already exists");
        poolMap[key] = poolAddr;
        allPools.push(poolAddr);

        emit PoolCreated(poolAddr, _tokens);
    }

    function getPool(address[] memory _tokens) view external returns (address) {
        uint key;
        for (uint i = 0; i < _tokens.length; i++) {
            key += uint(uint160(_tokens[i]));
        }
        return poolMap[key];
    }
}

