contract StablePool is ERC20 {

    // Number of tokens
    uint public immutable N;
    uint private immutable A;
    // 0.03%
    uint public constant SWAP_FEE = 300;
    // swap fee = add liquidity fee + remove liquidity fee
    uint public immutable LIQUIDITY_FEE;
    uint public constant FEE_DENOMINATOR = 1e6;
    uint public constant PROTOCOL_FEE_DENOMINATOR = 4; // 1/4 0f SWAP_FEE goes to protocol

    address public immutable factory;
    address[] public tokens;
    // Normalize each token to 18 decimals
    // Example - DAI (18 decimals), USDC (6 decimals), USDT (6 decimals)
    uint[] private multipliers;
    uint[] public balances;

    constructor(address[] memory _tokens, string memory _name, string memory _symbol) ERC20(_name, _symbol) {
        factory = msg.sender;
        tokens = _tokens;
        N = _tokens.length;
        A = 1000 * (_tokens.length ** (_tokens.length - 1));
        LIQUIDITY_FEE = (SWAP_FEE * _tokens.length) / (4 * (_tokens.length - 1));
        for (uint i = 0; i < _tokens.length; i++) {
            multipliers.push(10 ** (18 - ERC20(_tokens[i]).decimals()));
            balances.push(0);
        }
    }

    function _xp() private view returns (uint[] memory xp) {
        xp = new uint[](N);
        for (uint i; i < N; ++i) {
            xp[i] = balances[i] * multipliers[i];
        }
    }

    function _getD(uint[] memory xp) private view returns (uint) {
        uint a = A * N;

        uint s;
        for (uint i; i < N; ++i) {
            s += xp[i];
        }

        uint d = s;
        uint d_prev;
        for (uint i; i < 255; ++i) {
            uint p = d;
            for (uint j; j < N; ++j) {
                p = (p * d) / (N * xp[j]);
            }
            d_prev = d;
            d = ((a * s + N * p) * d) / ((a - 1) * d + (N + 1) * p);

            if (_abs(d, d_prev) <= 1) {
                return d;
            }
        }
        revert("D didn't converge");
    }

    function _getY(
        uint i,
        uint j,
        uint x,
        uint[] memory xp
    ) private view returns (uint) {
        uint a = A * N;
        uint d = _getD(xp);
        uint s;
        uint c = d;

        uint _x;
        for (uint k; k < N; ++k) {
            if (k == i) {
                _x = x;
            } else if (k == j) {
                continue;
            } else {
                _x = xp[k];
            }

            s += _x;
            c = (c * d) / (N * _x);
        }
        c = (c * d) / (N * a);
        uint b = s + d / a;

        uint y_prev;
        uint y = d;
        for (uint _i; _i < 255; ++_i) {
            y_prev = y;
            y = (y * y + c) / (2 * y + b - d);
            if (_abs(y, y_prev) <= 1) {
                return y;
            }
        }
        revert("y didn't converge");
    }

    function _getYD(uint i, uint[] memory xp, uint d) private view returns (uint) {
        uint a = A * N;
        uint s;
        uint c = d;

        uint _x;
        for (uint k; k < N; ++k) {
            if (k != i) {
                _x = xp[k];
            } else {
                continue;
            }

            s += _x;
            c = (c * d) / (N * _x);
        }
        c = (c * d) / (N * a);
        uint b = s + d / a;

        uint y_prev;
        uint y = d;
        for (uint _i; _i < 255; ++_i) {
            y_prev = y;
            y = (y * y + c) / (2 * y + b - d);
