    }

    function _abs(uint x, uint y) private pure returns (uint) {
        return x >= y ? x - y : y - x;
    }

    // How many tokens is one share worth?
    function getVirtualPrice() external view returns (uint) {
        uint d = _getD(_xp());
        uint _totalSupply = totalSupply();
        if (_totalSupply > 0) {
            return (d * 10 ** decimals()) / _totalSupply;
        }
        return 0;
    }

    /**
     * @notice Swap dx amount of token i for token j
     * @param i Index of token in
     * @param j Index of token out
     * @param dx Token in amount
     * @param minDy Minimum token out
     */
    function swap(uint i, uint j, uint dx, uint minDy) external returns (uint dy) {
        require(i != j, "i = j");

        ERC20(tokens[i]).transferFrom(msg.sender, address(this), dx);
        uint fee;
        (dy, fee) = getAmountOut(i, j, dx);
        require(dy >= minDy, "dy < min");

        //if factory is contract or not
        address feeToAddr = factory.code.length > 0 ? IFactory(factory).owner() : factory;
        uint protocolFee = fee / PROTOCOL_FEE_DENOMINATOR;

        balances[i] += dx;
        balances[j] -= (dy + protocolFee);

        ERC20(tokens[j]).transfer(feeToAddr, protocolFee);
        ERC20(tokens[j]).transfer(msg.sender, dy);
    }

    function getAmountOut(uint i, uint j, uint dx) view public returns (uint dy, uint fee) {
        uint[] memory xp = _xp();
        uint x = xp[i] + dx * multipliers[i];

        uint y0 = xp[j];
        uint y1 = _getY(i, j, x, xp);
        dy = (y0 - y1 - 1) / multipliers[j];

        fee = (dy * SWAP_FEE) / FEE_DENOMINATOR;
        dy -= fee;
    }

    function addLiquidity(
        uint[] calldata amounts,
        uint minShares
    ) external returns (uint shares) {
        shares = calcAddLiquidity(amounts);
        require(shares >= minShares, "shares < min");

        for (uint i; i < N; ++i) {
            uint amount = amounts[i];
            if (amount > 0) {
                ERC20(tokens[i]).transferFrom(msg.sender, address(this), amount);
                balances[i] += amount;
            }
        }
        _mint(msg.sender, shares);
    }

    function calcAddLiquidity(uint[] memory amounts) public view returns (uint shares) {
        uint _totalSupply = totalSupply();
        uint d0;
        uint[] memory old_xs = _xp();
        if (_totalSupply > 0) {
            d0 = _getD(old_xs);
        }

        uint[] memory new_xs = new uint[](N);
        for (uint i; i < N; ++i) {
            uint amount = amounts[i];
            if (amount > 0) {
                new_xs[i] = old_xs[i] + amount * multipliers[i];
            } else {
                new_xs[i] = old_xs[i];
            }
        }

        uint d1 = _getD(new_xs);
        require(d1 > d0, "liquidity didn't increase");

        uint d2;
        if (_totalSupply > 0) {
            for (uint i; i < N; ++i) {
                uint idealBalance = (old_xs[i] * d1) / d0;
                uint diff = _abs(new_xs[i], idealBalance);
                new_xs[i] -= (LIQUIDITY_FEE * diff) / FEE_DENOMINATOR;
            }

            d2 = _getD(new_xs);
        } else {
            d2 = d1;
        }

        if (_totalSupply > 0) {
            shares = ((d2 - d0) * _totalSupply) / d0;
        } else {
            shares = d2;
        }
    }

    function removeLiquidity(
        uint shares,
        uint[] calldata minAmountsOut
    ) external returns (uint[] memory amountsOut) {
        uint _totalSupply = totalSupply();
        amountsOut = new uint[](N);

        for (uint i; i < N; ++i) {
            uint amountOut = (balances[i] * shares) / _totalSupply;
            require(amountOut >= minAmountsOut[i], "out < min");

            balances[i] -= amountOut;
            amountsOut[i] = amountOut;

            ERC20(tokens[i]).transfer(msg.sender, amountOut);
        }

        _burn(msg.sender, shares);
    }

    function _calcWithdrawOneToken(
        uint shares,
        uint i
    ) private view returns (uint dy, uint fee) {
        uint _totalSupply = totalSupply();
        uint[] memory xp = _xp();

        uint d0 = _getD(xp);
        uint d1 = d0 - (d0 * shares) / _totalSupply;

        uint y0 = _getYD(i, xp, d1);
        uint dy0 = (xp[i] - y0) / multipliers[i];

        uint dx;
        for (uint j; j < N; ++j) {
            if (j == i) {
                dx = (xp[j] * d1) / d0 - y0;
            } else {
                dx = xp[j] - (xp[j] * d1) / d0;
            }
            xp[j] -= (LIQUIDITY_FEE * dx) / FEE_DENOMINATOR;
        }

        uint y1 = _getYD(i, xp, d1);
        dy = (xp[i] - y1 - 1) / multipliers[i];
        fee = dy0 - dy;
    }

    function calcWithdrawOneToken(
        uint shares,
        uint i
    ) external view returns (uint dy, uint fee) {
        return _calcWithdrawOneToken(shares, i);
    }

    /**
     * @notice Withdraw liquidity in token i
     * @param shares Shares to burn
     * @param i Token to withdraw
     * @param minAmountOut Minimum amount of token i that must be withdrawn
     */
    function removeLiquidityOneToken(
        uint shares,
        uint i,
        uint minAmountOut
    ) external returns (uint amountOut) {
        (amountOut, ) = _calcWithdrawOneToken(shares, i);
        require(amountOut >= minAmountOut, "out < min");

        balances[i] -= amountOut;
        _burn(msg.sender, shares);

        ERC20(tokens[i]).transfer(msg.sender, amountOut);
    }
}
